  const user = await createUser({ name: "Ada" });
  assert.equal(user.name, "Ada");
});

import { db } from "./db.js";
export async function report() {
  const users = await db.user.findMany();
  const teams = await db.team.findMany();
  return users.map((user) => ({ ...user, team: teams.find((team) => team.id === user.teamId) }));
}

import { db } from "./db.js";
export async function labelSelectedUsers(selectedIds: string[]) {
  const users = await db.user.findMany({ where: { id: { in: selectedIds } } });
  const labels = await db.label.findMany({ where: { userId: { in: selectedIds } } });
  // selectedIds is capped at 10 by the API schema; this preserves locale-aware application sorting.
  return users.map((user) => ({ ...user, labels: labels.filter((label) => label.userId === user.id) }));
}
